preamble:
// The v(t) sketch for 3(d), drawn to fill the answer box.  Three straight
// segments: powered ascent (slope +8.0), coast to the apex and the fall
// (both slope -10).
#let vt-graph(w, h) = {
  let pad-l = 0.42cm
  let pad-t = 0.55cm
  let plot-w = w - pad-l - 0.20cm
  let plot-h = h - pad-t - 0.50cm
  let t-max = 30.0
  let v-top = 80.0
  let v-bot = -120.0
  let px(t) = pad-l + plot-w * (t / t-max)
  let py(v) = pad-t + plot-h * ((v-top - v) / (v-top - v-bot))
  let seg(t1, v1, t2, v2, ..a) = place(top + left,
    line(start: (px(t1), py(v1)), end: (px(t2), py(v2)), ..a))
  let lbl(t, v, dx, dy, body) = place(top + left,
    dx: px(t) + dx, dy: py(v) + dy, text(size: 6.5pt, fill: key-red, body))
  box(width: w, height: h, {
    place(top + left, line(start: (px(0), py(0)), end: (w - 0.08cm, py(0)),
      stroke: 0.5pt + luma(130)))
    place(top + left, line(start: (px(0), pad-t - 0.12cm),
      end: (px(0), h - 0.10cm), stroke: 0.5pt + luma(130)))
    place(top + left, dx: px(0) + 0.08cm, dy: pad-t - 0.30cm,
      text(size: 6.5pt, fill: luma(90))[$v$ (m/s)])
    place(top + left, dx: w - 0.70cm, dy: py(0) + 0.06cm,
      text(size: 6.5pt, fill: luma(90))[$t$ (s)])
    seg(0, 0, 10, 80, stroke: 1.1pt + key-red)
    seg(10, 80, 18, 0, stroke: 1.1pt + key-red)
    seg(18, 0, 30, -120, stroke: 1.1pt + key-red)
    let dot(t, v) = place(top + left, dx: px(t) - 0.05cm, dy: py(v) - 0.05cm,
      circle(radius: 0.05cm, fill: key-red, stroke: none))
    dot(0, 0); dot(10, 80); dot(18, 0); dot(30, -120)
    lbl(0, 0, 0.08cm, 0.06cm)[liftoff (0 s, 0)]
    lbl(10, 80, -0.30cm, -0.36cm)[cut-off (10 s, #sym.plus\80 m/s)]
    lbl(18, 0, -0.10cm, -0.48cm)[highest (18.0 s, 0)]
    lbl(30, -120, -2.45cm, 0.02cm)[impact (30.0 s, #sym.minus\120 m/s)]
    lbl(4, 22, 0.00cm, 0.00cm)[slope #sym.plus\8.0]
    lbl(24, -60, -1.40cm, -0.10cm)[slope #sym.minus\10]
  })
}
